/* Shared utilities: only enquiry, photo/room dialogs and design-review controls.
   Page-specific navigation and browsing live in separate, design-scoped blocks below. */
const q=s=>document.querySelector(s),qa=s=>Array.from(document.querySelectorAll(s));
const design=document.body.dataset.design,reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const roomInfo=[{name:'Double Room',image:'bed',facts:'Carved four-poster bed · Heritage furniture',description:'A traditional double bedroom with a carved four-poster bed and patterned fabrics.'},{name:'AC Double Room',image:'bed1',facts:'Double bed · Air conditioning',description:'An air-conditioned double room with period furniture and a soft patterned palette.'},{name:'Heritage Suite',image:'bed2',facts:'Suite accommodation · Period furnishings',description:'A suite with the mansion’s distinctive furniture and old-world character.'}];
const dateValue=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function dayAfter(value){const d=new Date(value+'T12:00:00');d.setDate(d.getDate()+1);return dateValue(d)}
const stay=q('#stay-dialog'),stayForm=q('#stay-form');stayForm.elements.arrival.min=dateValue(new Date());stayForm.elements.departure.min=dayAfter(stayForm.elements.arrival.min);
function updateDeparture(){const min=dayAfter(stayForm.elements.arrival.value||dateValue(new Date()));stayForm.elements.departure.min=min;if(stayForm.elements.departure.value&&stayForm.elements.departure.value<min)stayForm.elements.departure.value=''}stayForm.elements.arrival.addEventListener('change',updateDeparture);
function closeDialogs(){qa('dialog[open]').forEach(d=>d.close())}
function enquire(room,dates){closeDialogs();q('#message-review').hidden=true;stayForm.hidden=false;q('#form-error').textContent='';if(room)stayForm.elements.room.value=room;if(dates){stayForm.elements.arrival.value=dates.arrival||'';stayForm.elements.departure.value=dates.departure||'';if(dates.adults)stayForm.elements.adults.value=dates.adults;updateDeparture()}stay.showModal()}
let detailRoom=0;function showRoom(index){detailRoom=Number(index);const r=roomInfo[detailRoom];if(!r)return;q('#room-dialog-title').textContent=r.name;q('#room-dialog-description').textContent=r.description;q('#room-dialog-facts').textContent=r.facts;q('#room-dialog-image').src=`../assets/${r.image}-enhanced.jpg`;q('#room-dialog-image').alt=r.name;closeDialogs();q('#room-dialog').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-enquire],[data-room-detail],[data-gallery-photo],[data-menu],[data-info],.dialog-close');if(!b)return;if(b.matches('.dialog-close')){b.closest('dialog').close();return}if(b.hasAttribute('data-enquire')){enquire(b.dataset.choice);return}if(b.hasAttribute('data-room-detail')){showRoom(b.dataset.roomDetail);return}if(b.hasAttribute('data-gallery-photo')){q('#large-image').src=`../assets/${b.dataset.galleryPhoto}-enhanced.jpg`;q('#large-image').alt=b.querySelector('img')?.alt||'Property photograph';q('#image-dialog').showModal();return}if(b.hasAttribute('data-menu')){const nav=q('#navigation-dialog');nav?.showModal();b.setAttribute('aria-expanded','true')}if(b.hasAttribute('data-info'))q('#notes-dialog').showModal()});
q('#room-dialog-enquire').addEventListener('click',()=>enquire(roomInfo[detailRoom].name));
stayForm.addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(stayForm));if(!d.name.trim()){q('#form-error').textContent='Please enter your name.';stayForm.elements.name.focus();return}if(d.arrival<dateValue(new Date())||d.departure<=d.arrival){q('#form-error').textContent='Select an arrival today or later and a departure after arrival.';return}const readable=x=>new Date(x+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}),nights=Math.round((Date.parse(d.departure+'T12:00:00')-Date.parse(d.arrival+'T12:00:00'))/86400000);const text=`Hello Necila, I would like to enquire about a stay at Palacete Rodrigues.\n\nName: ${d.name.trim()}\nEmail: ${d.email}\nArrival: ${readable(d.arrival)}\nDeparture: ${readable(d.departure)}\nNights: ${nights}\nAdults: ${d.adults}\nChildren: ${d.children}\nRoom preference: ${d.room}${d.notes.trim()?'\nNotes: '+d.notes.trim():''}\n\nPlease share availability, total rates and booking terms. Thank you!`;q('#message-body').textContent=text;q('#send-whatsapp').href='https://wa.me/919881284340?text='+encodeURIComponent(text);q('#send-email').href='mailto:palaceterodriguesgoa@gmail.com?subject='+encodeURIComponent('Stay enquiry | '+readable(d.arrival))+'&body='+encodeURIComponent(text);stayForm.hidden=true;q('#message-review').hidden=false;q('#send-whatsapp').focus()});
q('#edit-message').addEventListener('click',()=>{q('#message-review').hidden=true;stayForm.hidden=false;stayForm.elements.name.focus()});
qa('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.addEventListener('close',()=>qa('[data-menu]').forEach(b=>b.setAttribute('aria-expanded','false')))});
qa('#navigation-dialog nav a').forEach(a=>a.addEventListener('click',()=>q('#navigation-dialog').close()));
function saved(){try{const s=JSON.parse(localStorage.getItem('palacete-shortlist')||'[]');return Array.isArray(s)?s:[]}catch{return[]}}function updateSave(){const on=saved().includes(design);q('#save-design').setAttribute('aria-pressed',String(on));q('#save-design').textContent=on?'♥ Shortlisted':'♡ Shortlist'}updateSave();q('#save-design').onclick=()=>{const list=saved(),newList=list.includes(design)?list.filter(x=>x!==design):[...list,design];try{localStorage.setItem('palacete-shortlist',JSON.stringify(newList))}catch{}updateSave()};q('#design-select').onchange=e=>{location.href=e.target.value+'.html'};q('#hide-review').onclick=()=>{q('.review-bar').hidden=true;q('#show-review').hidden=false};q('#show-review').onclick=()=>{q('.review-bar').hidden=false;q('#show-review').hidden=true};
if(!reduceMotion&&'IntersectionObserver'in window){document.body.classList.add('motion-enabled');const obs=new IntersectionObserver(items=>items.forEach(item=>{if(item.isIntersecting){item.target.classList.add('entered');obs.unobserve(item.target)}}),{threshold:.08});qa('.film-interlude,.article-body h2,.azul-colophon,.edit-room-edition>header,.post-letter,.museum-provenance,.utility-practical').forEach(el=>{el.classList.add('enter-observe');obs.observe(el)})}
// CASA: an annotated journal index. The note and adjacent plate change together.
if(design==='casa'){let active=0;const tabs=qa('[data-note]');function setNote(n,focus=false){active=(n+tabs.length)%tabs.length;tabs.forEach((t,i)=>{t.setAttribute('aria-selected',String(i===active));t.tabIndex=i===active?0:-1});const r=roomInfo[active];q('#note-panel').setAttribute('aria-labelledby',tabs[active].id);const img=q('#note-photo-button img');img.src=`../assets/${r.image}-enhanced.jpg`;img.alt=r.name;q('#note-photo-button').dataset.roomDetail=String(active);q('#note-copy').textContent=r.description;if(focus)tabs[active].focus()}tabs.forEach((b,i)=>{b.onclick=()=>setNote(i);b.onkeydown=e=>{if(e.key==='ArrowDown'||e.key==='ArrowRight'){e.preventDefault();setNote(active+1,true)}if(e.key==='ArrowUp'||e.key==='ArrowLeft'){e.preventDefault();setNote(active-1,true)}}});q('#note-enquire').onclick=()=>enquire(roomInfo[active].name);setNote(0)}
// JARDIM: restrained parallax only. Native scrolling and sticky room layers remain intact.
if(design==='jardim'&&!reduceMotion){let queued=false;function move(){qa('[data-parallax]').forEach(el=>{const rect=el.getBoundingClientRect(),speed=Number(el.dataset.parallax),shift=Math.max(-30,Math.min(30,(rect.top+rect.height/2-innerHeight/2)*speed));el.style.transform=`translateY(${shift}px)`});queued=false}addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(move)}},{passive:true});move()}
// POSTCARD: a stacked deck. Inactive cards are inert and removed from accessibility navigation.
if(design==='postcard'){let index=0;const cards=qa('[data-card]'),deck=q('.post-room-deck');function turn(n){index=(n+cards.length)%cards.length;cards.forEach((card,i)=>{const front=i===index;card.classList.toggle('is-front',front);card.inert=!front;card.setAttribute('aria-hidden',String(!front))});q('#deck-position').textContent=`${index+1} / ${cards.length}`};q('[data-deck-prev]').onclick=()=>turn(index-1);q('[data-deck-next]').onclick=()=>turn(index+1);deck.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();turn(index+1)}if(e.key==='ArrowLeft'){e.preventDefault();turn(index-1)}});turn(0)}
// ATLAS: date-first utility form and a single segmented comparison panel.
if(design==='atlas'){const quick=q('#quick-planner'),tabs=qa('[data-utility-room]');quick.elements.arrival.min=dateValue(new Date());quick.elements.departure.min=dayAfter(quick.elements.arrival.min);quick.elements.arrival.onchange=()=>{quick.elements.departure.min=dayAfter(quick.elements.arrival.value||dateValue(new Date()));if(quick.elements.departure.value&&quick.elements.departure.value<quick.elements.departure.min)quick.elements.departure.value=''};quick.onsubmit=e=>{e.preventDefault();enquire(undefined,{arrival:quick.elements.arrival.value,departure:quick.elements.departure.value,adults:quick.elements.guests.value})};let active=0;function pick(n,focus=false){active=(n+tabs.length)%tabs.length;tabs.forEach((b,i)=>{b.setAttribute('aria-selected',String(i===active));b.tabIndex=i===active?0:-1});const r=roomInfo[active];q('#utility-room-panel').setAttribute('aria-labelledby',tabs[active].id);q('#utility-room-name').textContent=r.name;q('#utility-room-copy').textContent=r.description;q('#utility-room-type').textContent=['TRADITIONAL DOUBLE','AIR-CONDITIONED DOUBLE','HERITAGE SUITE'][active];q('#utility-room-image img').src=`../assets/${r.image}-enhanced.jpg`;q('#utility-room-image img').alt=r.name;q('#utility-room-image').dataset.roomDetail=String(active);const facts=[...r.facts.split(' · '),'Rate by personal quote'];q('#utility-room-facts').replaceChildren(...facts.map(f=>{const li=document.createElement('li');li.textContent=f;return li}));if(focus)tabs[active].focus()}tabs.forEach((b,i)=>{b.onclick=()=>pick(i);b.onkeydown=e=>{if(e.key==='ArrowRight'){e.preventDefault();pick(active+1,true)}if(e.key==='ArrowLeft'){e.preventDefault();pick(active-1,true)}}});q('#utility-room-enquire').onclick=()=>enquire(roomInfo[active].name);pick(0)}
// New collection interactions; no outbound action is triggered automatically.
if(design==='concierge'){let active=0;qa('[data-desk]').forEach(b=>b.onclick=()=>{active=Number(b.dataset.desk);qa('[data-desk]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const r=roomInfo[active];q('#desk-name').textContent=r.name;q('#desk-copy').textContent=r.description;q('#desk-answer>img').src=`../assets/${r.image}-enhanced.jpg`;q('#desk-answer>img').alt=r.name});q('#desk-detail').onclick=()=>showRoom(active);q('#desk-enquire').onclick=()=>enquire(roomInfo[active].name)}
if(design==='together'){q('#party-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.currentTarget);enquire(undefined,{adults:d.get('partyAdults')});stayForm.elements.children.value=d.get('partyChildren');stayForm.elements.notes.value=`Group enquiry: ${d.get('partyRooms')} room(s) requested. Please advise suitable room arrangements and occupancy.`}}
if(design==='select'){let active=0;qa('[data-salon]').forEach(b=>b.onclick=()=>{active=Number(b.dataset.salon);qa('[data-salon]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));q('#salon-name').textContent=roomInfo[active].name;q('#salon-facts').textContent=roomInfo[active].facts});q('#salon-detail').onclick=()=>showRoom(active);q('#salon-enquire').onclick=()=>enquire(roomInfo[active].name)}
if(design==='village'){const places=[['new444','The house','Period furniture, a welcoming lounge and the character of a personal heritage home.'],['gardenview','The garden pool','A quieter afternoon between outings. Confirm current pool access and timings with your host.'],['furniture','Out in Anjuna','Set out at your own pace, with a heritage address to return to in Mazal Vaddo. Use the map link for the property location.']];qa('[data-place]').forEach(b=>b.onclick=()=>{const p=places[Number(b.dataset.place)];qa('[data-place]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));q('.place-note>img').src=`../assets/${p[0]}-enhanced.jpg`;q('.place-note>img').alt=p[1];q('#place-title').textContent=p[1];q('#place-copy').textContent=p[2]})}
if(design==='openhouse'){const scenes=[['new444','The lounge','Period furniture and collected details give the house its personal character.'],['furniture','The details','Look closer at the carved furniture and patterned interiors.'],['gardenview','The garden pool','A little time outdoors, a little less on the agenda.']];qa('[data-tour]').forEach(b=>b.onclick=()=>{const s=scenes[Number(b.dataset.tour)];qa('[data-tour]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));q('.tour-view>img').src=`../assets/${s[0]}-enhanced.jpg`;q('.tour-view>img').alt=s[1];q('#tour-title').textContent=s[1];q('#tour-copy').textContent=s[2];q('#tour-zoom').dataset.galleryPhoto=s[0]})}
